const PAIRS = [
 {id:"p1",s:"“There’s no best way: it depends on the environment.”",a:"con",b:"sys",why:"“It depends” is the signature of contingency. Systems theory talks about interdependencies, not which structure to choose."},
 {id:"p2",s:"“We changed the software, and roles, skills and collaboration changed too.”",a:"sys",b:"con",why:"Knock-on effects between technology, people and processes: the sociotechnical perspective."},
 {id:"p3",s:"“We cut costs by standardizing every movement.”",a:"cls",b:"eco",why:"Efficiency through method and standards: Taylor. The economic lens would talk about transactions and incentives."},
 {id:"p4",s:"“We make it in-house, because a contract with a supplier would be too risky.”",a:"eco",b:"cls",why:"Make-or-buy and hard-to-write contracts: transaction costs (Williamson)."},
 {id:"p5",s:"“People stay because they feel they belong to the group.”",a:"hr",b:"ins",why:"Belonging and informal relationships explain behaviour: Human Relations."},
 {id:"p6",s:"“We’re introducing remote work because that’s what people expect from a modern employer.”",a:"ins",b:"hr",why:"The motive is external expectation, i.e. legitimacy, not motivation: institutional."},
 {id:"p7",s:"“The manager picks the first solution that meets the minimum criteria.”",a:"dec",b:"cls",why:"That’s the definition of satisficing (Simon)."},
 {id:"p8",s:"“The department head plans, the workers execute.”",a:"cls",b:"dec",why:"Separating planning from execution is a pillar of the classical lens."},
 {id:"p9",s:"“Shareholders fear the CEO is pursuing his own interests.”",a:"eco",b:"dec",why:"Principal–agent conflict: agency theory."},
 {id:"p10",s:"“Nobody has all the information, so we create routines.”",a:"dec",b:"eco",why:"Routines as a response to bounded rationality: the decision-making lens."},
 {id:"p11",s:"“We take resources and information from the environment and give them back transformed.”",a:"sys",b:"con",why:"Input → transformation → output: the definition of an open system."},
 {id:"p12",s:"“We’re small and the market is stable: staying centralized works for us.”",a:"con",b:"sys",why:"Size and environment determine the fitting structure: fit, so contingency."},
 {id:"p13",s:"“I pay taxes and the state funds public universities.”",a:"pol",b:"bel",why:"A centre collects and redistributes: redistribution (Polanyi, Ch. 2)."},
 {id:"p14",s:"“If we believe resources are scarce, of course departments compete.”",a:"bel",b:"pol",why:"An assumption that generates values and practices: the Chapter 1 chain."},
 {id:"p15",s:"“Raising salaries stopped the complaints, but didn’t motivate anyone.”",a:"hr",b:"eco",why:"Hygiene factors versus motivators: Herzberg. The economic lens would only see the incentive."},
 {id:"p16",s:"“Every hospital has the same compliance office because the law requires it.”",a:"ins",b:"cls",why:"Coercive isomorphism: organizations become similar under external regulatory pressure."}
];
